const started = Date.now();
const round = (value, digits = 1) => Number(value.toFixed(digits));
const sequence = Number(flow.get('sampleSequence') || 0) + 1;
const appStartedAt = Number(flow.get('appStartedAt') || started);
flow.set('appStartedAt', appStartedAt);
flow.set('sampleSequence', sequence);
const phase = sequence / 3;
const generatedAt = new Date(started).toISOString();
const sampleKey = `NL-${String(sequence).padStart(8, '0')}`;
const stations = [
  {
    id:'cnc-cell', name:'CNC Cell', zone:'Machining bay', state:'RUNNING', health:'NORMAL', quality:'good',
    observedAt:generatedAt, temperatureC:round(24.2 + Math.sin(phase) * 1.5), thresholdC:30,
    powerKw:round(4.8 + Math.cos(phase * 0.8) * 0.7), processValue:Math.round((sequence * 7) % 100),
    processLabel:'Cycle progress', processUnit:'%'
  },
  {
    id:'curing-oven', name:'Curing Oven', zone:'Finishing bay', state:'HOLDING', health:'NORMAL', quality:'good',
    observedAt:generatedAt, temperatureC:round(68.5 + Math.sin(phase * 0.65) * 3.8), thresholdC:82,
    powerKw:round(8.7 + Math.cos(phase * 0.55) * 1.2), processValue:Math.round((sequence * 4 + 35) % 100),
    processLabel:'Batch progress', processUnit:'%'
  },
  {
    id:'packing-line', name:'Packing Line', zone:'Dispatch bay', state:'RUNNING', health:'NORMAL', quality:'good',
    observedAt:generatedAt, temperatureC:round(28.8 + Math.sin(phase * 1.2) * 1.1), thresholdC:42,
    powerKw:round(2.5 + Math.cos(phase) * 0.35), processValue:Math.round(44 + Math.sin(phase * 0.9) * 5),
    processLabel:'Throughput', processUnit:' packs/min'
  }
];
const generationLatencyMs = Math.max(0, Date.now() - started);
const tick = {schemaVersion:'2.0.0',sampleId:sequence,sampleKey,generatedAt,intervalMs:1500,stations,generationLatencyMs};
flow.set('latestTick', tick);
flow.set('ticksGenerated', sequence);
flow.set('messagesProcessed', Number(flow.get('messagesProcessed') || 0) + 1);
node.status({fill:'green',shape:'dot',text:`${sampleKey} · ${stations.length} emulated stations`});
return null;

const builtStarted = Date.now();
const allowed = {
  normal:{label:'Normal shift'},
  heating:{label:'Heating load'},
  fault:{label:'Fault and stale signal'},
  recover:{label:'Controlled recovery'}
};
const requested = String(msg.req?.query?.scenario || 'normal').toLowerCase();
msg.headers = {'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'};
if (!Object.prototype.hasOwnProperty.call(allowed, requested)) {
  msg.statusCode = 400;
  msg.payload = {accepted:false,error:'scenario must be normal, heating, fault or recover'};
  return msg;
}
const tick = flow.get('latestTick');
if (!tick) {
  msg.statusCode = 503;
  msg.payload = {accepted:false,error:'live generator is starting'};
  return msg;
}
const now = Date.now();
const snapshot = JSON.parse(JSON.stringify(tick));
const byId = Object.fromEntries(snapshot.stations.map((station) => [station.id, station]));
const events = [];
if (requested === 'normal') {
  events.push({level:'info',stationId:null,message:'All emulated workshop signals are inside their teaching limits.'});
}
if (requested === 'heating') {
  byId['cnc-cell'].temperatureC = Number((byId['cnc-cell'].temperatureC + 3.5).toFixed(1));
  byId['cnc-cell'].powerKw = Number((byId['cnc-cell'].powerKw + 1.1).toFixed(1));
  byId['cnc-cell'].state = 'LOAD RISING';
  byId['cnc-cell'].health = 'WATCH';
  byId['curing-oven'].temperatureC = Number((byId['curing-oven'].temperatureC + 8).toFixed(1));
  byId['curing-oven'].powerKw = Number((byId['curing-oven'].powerKw + 2.5).toFixed(1));
  byId['curing-oven'].state = 'HEATING';
  byId['curing-oven'].health = 'WATCH';
  events.push({level:'watch',stationId:'curing-oven',message:'Heating load is rising but remains below the emulated limit.'});
}
if (requested === 'fault') {
  byId['cnc-cell'].temperatureC = Number((byId['cnc-cell'].thresholdC + 5.2).toFixed(1));
  byId['cnc-cell'].powerKw = 0.6;
  byId['cnc-cell'].state = 'THERMAL TRIP';
  byId['cnc-cell'].health = 'ALERT';
  byId['packing-line'].temperatureC = null;
  byId['packing-line'].powerKw = null;
  byId['packing-line'].quality = 'missing';
  byId['packing-line'].observedAt = new Date(now - 10000).toISOString();
  byId['packing-line'].state = 'SIGNAL LOST';
  byId['packing-line'].health = 'STALE';
  events.push({level:'alert',stationId:'cnc-cell',message:'Thermal trip: emulated temperature crossed its limit.'});
  events.push({level:'alert',stationId:'packing-line',message:'Missing signal: the last emulated observation is stale.'});
}
if (requested === 'recover') {
  byId['cnc-cell'].temperatureC = Number((byId['cnc-cell'].thresholdC - 2.5).toFixed(1));
  byId['cnc-cell'].powerKw = 2.1;
  byId['cnc-cell'].state = 'COOL-DOWN';
  byId['cnc-cell'].health = 'RECOVERING';
  byId['curing-oven'].state = 'HOLDING';
  byId['packing-line'].state = 'RESTARTED';
  events.push({level:'recovery',stationId:'cnc-cell',message:'Recovery confirmed: valid emulated temperature is below the limit.'});
  events.push({level:'info',stationId:'packing-line',message:'Fresh packing-line signal restored for this response.'});
}
snapshot.stations = Object.values(byId).map((station) => {
  const validTemperature = Number.isFinite(station.temperatureC);
  const comfortMargin = validTemperature ? Number((station.thresholdC - station.temperatureC).toFixed(1)) : null;
  return {...station,comfort_margin_c:comfortMargin,ageMs:Math.max(0, now - Date.parse(station.observedAt))};
});
const primary = snapshot.stations.find((station) => station.id === 'cnc-cell');
snapshot.configured_demo_temperature_limit_c = primary.thresholdC;
snapshot.validated_temperature_c = Number.isFinite(primary.temperatureC) ? primary.temperatureC : null;
snapshot.comfort_margin_c = primary.comfort_margin_c;
const apiResponses = Number(flow.get('apiResponses') || 0) + 1;
flow.set('apiResponses', apiResponses);
const messagesProcessed = Number(flow.get('messagesProcessed') || 0) + 1;
flow.set('messagesProcessed', messagesProcessed);
const appStartedAt = Number(flow.get('appStartedAt') || now);
snapshot.scenario = {id:requested,label:allowed[requested].label,scope:'this-response-only'};
snapshot.source = {kind:'live-generated-emulation',hardwareConnected:false,physicalSensors:false,customerData:false};
snapshot.events = events.map((event,index) => ({...event,id:`${snapshot.sampleKey}-E${index + 1}`,at:snapshot.generatedAt}));
snapshot.runtime = {
  nodeRedVersion:'5.0.8',
  flowVersion:'2.0.0',
  uptimeSeconds:Math.max(0, Math.floor((now - appStartedAt) / 1000)),
  ticksGenerated:Number(flow.get('ticksGenerated') || 0),
  apiResponses,
  messagesProcessed,
  generationLatencyMs:Number(snapshot.generationLatencyMs || 0),
  responseBuildMs:Math.max(0, Date.now() - builtStarted),
  tickAgeMs:Math.max(0, now - Date.parse(snapshot.generatedAt)),
  generatorIntervalMs:1500
};
msg.statusCode = 200;
msg.payload = snapshot;
return msg;

const origin = String(msg.req?.headers?.origin || '');
const allowedOrigin = env.get('NODE_LAB_ALLOWED_ORIGIN') || 'http://127.0.0.1:1880';
const raw = msg.payload && typeof msg.payload === 'object' ? msg.payload.temperature : undefined;
msg.headers = {'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'};
if (origin !== allowedOrigin) {
    msg.statusCode = 403;
    msg.payload = {error:'same-origin request required'};
    return [null, msg];
}
if (typeof raw !== 'number' || !Number.isFinite(raw) || ![22,30,34].includes(raw)) {
    msg.statusCode = 400;
    msg.payload = {error:'sample must be the JSON number 22, 30 or 34', accepted:false};
    return [null, msg];
}
msg.payload = raw;
msg.topic = 'synthetic-temperature';
return [msg, null];

const temperature = Number(msg.payload);
const alert = temperature >= 30;
msg.statusCode = 200;
msg.headers = {'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'};
msg.payload = {
    accepted:true,
    temperature,
    threshold:30,
    validated_temperature_c:temperature,
    configured_demo_temperature_limit_c:30,
    comfort_margin_c:Number((30 - temperature).toFixed(1)),
    status:alert ? 'HIGH TEMPERATURE' : 'NORMAL OPERATION',
    source:'synthetic-demo',
    sequence:alert ? 'alert' : 'normal'
};
node.status({fill:alert ? 'red' : 'green',shape:'dot',text:temperature + ' C | ' + msg.payload.sequence});
return msg;
